1	// 本地整库备份与恢复:导出快照(backup)与从快照整库恢复(restore)。
2	//
3	// - 快照为单个 JSON 文件,含格式标识、格式版本、负载的 SHA-256 完整性校验和
4	//   及三个业务存储(读数与修正/撤销历史、告警规则与历史、分组成员版本)的
5	//   完整内容;毫千瓦时为十进制字符串,任意大数精确保留。快照文件必须位于
6	//   数据目录之外;已有输出文件拒绝覆盖(原子无覆盖创建),备份失败不留下
7	//   可被当作成功快照的输出(先写临时文件再原子链接为最终名)。
8	// - 备份与恢复都校验三个业务存储的结构与关联:全库重复读数身份、修正项引用
9	//   缺失读数、撤销引用缺失修正、分组成员或规则目标不存在、告警引用缺失规则,
10	//   任一问题指出原因并拒绝。缺失的存储文件按对应空状态处理。
11	// - 恢复为整库替换:成功后业务状态完全等于快照,快照为空的部分清除原数据,
12	//   快照之后新增的读数、请求和告警不保留;只替换三个业务存储文件,目录内
13	//   其他文件保持不变;不自动评估或重新生成历史。恢复可用于当前存储已损坏
14	//   的目录,不解析原库。
15	// - 三个业务存储作为一次恢复提交,恢复日志(journal)用阶段字段记录进度:
16	//   preparing(准备,可收敛为完整旧库或完整快照)→ committing(整体换名,
17	//   只能前滚为完整快照)→ rolling-back(已进入失败回滚,只能继续还原完整
18	//   旧库,不能改为前滚)→ done。任何阶段被杀死,任一命令再次启动都会先
19	//   取得目录操作权并续接未完成恢复;已还原的旧文件绝不误删,原本缺失的
20	//   文件恢复为缺失,不把事务造成的缺文件当成空库。无法可靠判定或完成一致
21	//   恢复时报错返回 1,保留全部续接材料,不输出业务结果、不做业务写入。
22	// - 任一命令从取得数据目录操作权起,先处理未完成恢复,再执行业务查询或
23	//   写入。操作权是按数据目录隔离的排他锁:同目录被其他存活进程占用时明确
24	//   拒绝返回 1,不读写业务存储、不清理对方事务材料;属主退出后可安全接管,
25	//   不同数据目录互不阻塞。备份、恢复与启动自恢复期间同样持锁。
26	
27	import { createHash } from 'node:crypto';
28	import {
29	  closeSync,
30	  existsSync,
31	  mkdirSync,
32	  openSync,
33	  readFileSync,
34	  readdirSync,
35	  renameSync,
36	  rmSync,
37	  statSync,
38	  writeFileSync,
39	  linkSync,
40	} from 'node:fs';
41	import { basename, isAbsolute, join, relative, resolve } from 'node:path';
42	import {
43	  alertFilePath,
44	  dataDirPath,
45	  dataFilePath,
46	  groupFilePath,
47	  loadData,
48	  parseStoreData,
49	  serializeStoreData,
50	  StoreError,
51	  type StoreData,
52	} from './store.ts';
53	import {
54	  loadAlertState,
55	  parseAlertState,
56	  serializeAlertState,
57	  type AlertState,
58	} from './alerts.ts';
59	import { loadGroups, parseGroups, serializeGroups, type Group } from './groups.ts';
60	import { formatIsoUtc } from './time.ts';
61	
62	const SNAPSHOT_FORMAT = 'meterwatch-snapshot';
63	const SNAPSHOT_VERSION = 1;
64	
65	const LOCK_NAME = 'meterwatch.lock';
66	const JOURNAL_NAME = 'restore.journal';
67	const JOURNAL_FORMAT = 'meterwatch-restore-journal';
68	const NEW_SUFFIX = '.restore-new';
69	const OLD_SUFFIX = '.restore-old';
70	
71	/** 恢复阶段;阶段只能按声明的顺序推进,字段缺失按最保守的 committing 处理。 */
72	type RestorePhase = 'preparing' | 'committing' | 'rolling-back' | 'done';
73	const PHASES: RestorePhase[] = ['preparing', 'committing', 'rolling-back', 'done'];
74	
75	function err(message: string): void {
76	  console.error(`meterwatch: ${message}`);
77	}
78	
79	/** 三个业务存储文件的绝对路径(顺序固定,恢复作为一次提交)。 */
80	function storeFiles(): string[] {
81	  return [dataFilePath(), alertFilePath(), groupFilePath()];
82	}
83	
84	/** 快照路径是否位于数据目录之内(含等于目录本身)。 */
85	function isInsideDir(dir: string, p: string): boolean {
86	  const rel = relative(resolve(dir), resolve(p));
87	  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
88	}
89	
90	/**
91	 * 校验三个业务存储的关联一致性(结构合法性由各自的解析函数保证)。
92	 * 返回问题列表,空数组表示一致。
93	 */
94	function validateStores(data: StoreData, alerts: AlertState, groups: Group[]): string[] {
95	  const problems: string[] = [];
96	
97	  // 全库重复读数身份:同一设备同一实际时刻只允许一条存储记录。
98	  const readingKeys = new Set<string>();
99	  for (const r of data.readings) {
100	    const k = `${r.device} ${r.ts}`;
101	    if (readingKeys.has(k)) {
102	      problems.push(`duplicate stored reading for device '${r.device}' at ${formatIsoUtc(r.ts)}`);
103	    } else {
104	      readingKeys.add(k);
105	    }
106	  }
107	
108	  // 修正项必须引用已存读数。
109	  for (const c of data.corrections) {
110	    for (const it of c.items) {
111	      if (!readingKeys.has(`${it.device} ${it.ts}`)) {
112	        problems.push(
113	          `correction '${c.requestId}' references missing reading ` +
114	            `(device='${it.device}' at ${formatIsoUtc(it.ts)})`,
115	        );
116	      }
117	    }
118	  }
119	
120	  // 撤销必须引用已存修正。
121	  const correctionIds = new Set(data.corrections.map((c) => c.requestId));
122	  for (const u of data.undos) {
123	    if (!correctionIds.has(u.targetId)) {
124	      problems.push(`undo '${u.requestId}' references missing correction '${u.targetId}'`);
125	    }
126	  }
127	
128	  // 分组成员必须是已有读数的设备。
129	  const devices = new Set(data.readings.map((r) => r.device));
130	  for (const g of groups) {
131	    for (const v of g.versions) {
132	      for (const m of v.members) {
133	        if (!devices.has(m)) {
134	          problems.push(`group '${g.id}' member '${m}' has no stored readings`);
135	        }
136	      }
137	    }
138	  }
139	
140	  // 规则目标必须存在:设备规则绑定有读数的设备,分组规则绑定已配置分组。
141	  const groupIds = new Set(groups.map((g) => g.id));
142	  for (const r of alerts.rules) {
143	    if (r.targetType === 'device' && !devices.has(r.targetId)) {
144	      problems.push(`rule '${r.id}' targets device '${r.targetId}' which has no stored readings`);
145	    }
146	    if (r.targetType === 'group' && !groupIds.has(r.targetId)) {
147	      problems.push(`rule '${r.id}' targets unknown group '${r.targetId}'`);
148	    }
149	  }
150	
151	  // 告警必须引用已存规则。
152	  const ruleIds = new Set(alerts.rules.map((r) => r.id));
153	  for (const a of alerts.alerts) {
154	    if (!ruleIds.has(a.ruleId)) {
155	      problems.push(`alert '${a.id}' references missing rule '${a.ruleId}'`);
156	    }
157	  }
158	
159	  return problems;
160	}
161	
162	// ---------------------------------------------------------------------------
163	// 目录操作权(排他锁,按数据目录隔离)
164	// ---------------------------------------------------------------------------
165	
166	/**
167	 * 获取数据目录的排他操作权;成功返回 null,失败返回错误消息。
168	 * 锁文件已存在且属存活进程时拒绝(不读写业务存储、不清理对方事务材料);
169	 * 属已退出进程时清理后重试一次(其未完成恢复由接管方持锁续接)。
170	 */
171	function acquireLock(dir: string): string | null {
172	  const lockPath = join(dir, LOCK_NAME);
173	  for (let attempt = 0; attempt < 2; attempt++) {
174	    try {
175	      const fd = openSync(lockPath, 'wx');
176	      try {
177	        writeFileSync(fd, `${process.pid}\n`);
178	      } finally {
179	        closeSync(fd);
180	      }
181	      return null;
182	    } catch (e) {
183	      const code = (e as NodeJS.ErrnoException).code;
184	      if (code !== 'EEXIST') {
185	        return `cannot acquire directory lock ${lockPath}: ${(e as Error).message}`;
186	      }
187	      let pid = Number.NaN;
188	      try {
189	        pid = Number(readFileSync(lockPath, 'utf8').trim());
190	      } catch {
191	        // 读不出属主按存活处理,不冒险清理。
192	      }
193	      let alive = true;
194	      if (Number.isInteger(pid) && pid > 0) {
195	        try {
196	          process.kill(pid, 0);
197	        } catch (ke) {
198	          alive = (ke as NodeJS.ErrnoException).code === 'EPERM';
199	        }
200	      }
201	      if (alive) {
202	        return (
203	          `data directory ${dir} is locked by another live meterwatch process` +
204	          `${Number.isInteger(pid) && pid > 0 ? ` (pid ${pid})` : ''}; ` +
205	          `wait for it to finish, or use another data directory`
206	        );
207	      }
208	      try {
209	        rmSync(lockPath);
210	      } catch (re) {
211	        return `cannot remove stale lock ${lockPath}: ${(re as Error).message}`;
212	      }
213	    }
214	  }
215	  return `cannot acquire directory lock ${join(dir, LOCK_NAME)}`;
216	}
217	
218	function releaseLock(dir: string): void {
219	  try {
220	    rmSync(join(dir, LOCK_NAME));
221	  } catch {
222	    // 锁文件可能已被清理;释放失败不影响已完成的操作。
223	  }
224	}
225	
226	/** 目标是否为常规文件;路径不存在返回 false,其他类型(目录等)返回 false。 */
227	function isRegularFile(p: string): boolean {
228	  try {
229	    return statSync(p).isFile();
230	  } catch {
231	    return false;
232	  }
233	}
234	
235	// ---------------------------------------------------------------------------
236	// 恢复日志
237	// ---------------------------------------------------------------------------
238	
239	interface JournalFile {
240	  /** 业务存储文件名(basename)。 */
241	  name: string;
242	  /** 恢复前该文件是否存在(原本缺失的,回滚后必须仍为缺失)。 */
243	  hadOld: boolean;
244	}
245	
246	interface Journal {
247	  phase: RestorePhase;
248	  files: JournalFile[];
249	}
250	
251	/**
252	 * 解析恢复日志。结构非法返回 null:调用方按无法可靠判定处理,绝不猜测,
253	 * 也不清理仍可用于恢复的材料。
254	 */
255	function parseJournal(data: unknown): Journal | null {
256	  const o = data as Record<string, unknown>;
257	  if (
258	    o === null ||
259	    typeof o !== 'object' ||
260	    o.format !== JOURNAL_FORMAT ||
261	    o.version !== 1 ||
262	    !Array.isArray(o.files) ||
263	    o.files.length === 0
264	  ) {
265	    return null;
266	  }
267	  // 旧/缺阶段字段按最保守的 committing 处理(只能前滚)。
268	  let phase: RestorePhase = 'committing';
269	  if (typeof o.phase === 'string' && (PHASES as string[]).includes(o.phase)) {
270	    phase = o.phase as RestorePhase;
271	  }
272	  const names = new Set<string>();
273	  const files: JournalFile[] = [];
274	  for (const f of o.files as Array<Record<string, unknown>>) {
275	    if (
276	      f === null ||
277	      typeof f !== 'object' ||
278	      typeof f.name !== 'string' ||
279	      f.name.length === 0 ||
280	      basename(f.name as string) !== f.name ||
281	      typeof f.hadOld !== 'boolean' ||
282	      names.has(f.name as string)
283	    ) {
284	      return null;
285	    }
286	    names.add(f.name as string);
287	    files.push({ name: f.name as string, hadOld: f.hadOld as boolean });
288	  }
289	  return { phase, files };
290	}
291	
292	/** 原子改写日志阶段(先写临时文件再换名)。失败抛错,材料保留。 */
293	function writeJournalPhase(dir: string, journal: Journal, phase: RestorePhase): void {
294	  const journalPath = join(dir, JOURNAL_NAME);
295	  const tmp = `${journalPath}.tmp-${process.pid}`;
296	  writeFileSync(
297	    tmp,
298	    JSON.stringify(
299	      { format: JOURNAL_FORMAT, version: 1, phase, files: journal.files },
300	      null,
301	      2,
302	    ) + '\n',
303	    'utf8',
304	  );
305	  renameSync(tmp, journalPath);
306	  journal.phase = phase;
307	}
308	
309	// ---------------------------------------------------------------------------
310	// 回滚(还原完整旧库)——幂等,可跨中断续接
311	// ---------------------------------------------------------------------------
312	
313	/**
314	 * 回滚到恢复前状态。必须在 journal.phase === 'rolling-back' 下调用。
315	 *
316	 * 幂等且可在任意一步中断后续接:
317	 * - 旧文件备份存在:原位若为常规文件则删除,再把备份原子换回(rename 覆盖
318	 *   已先删除,故不会因 EEXIST 失败);已还原到原位的旧文件不会被误删。
319	 * - 原本缺失(hadOld=false):旧备份按定义不存在;删除事务换入的新内容,
320	 *   恢复为缺失。原位不存在时即为已完成,绝不把缺文件当成空库而补写。
321	 * - hadOld=true 但原位与旧备份同时缺失:状态被外部破坏,无法可靠还原,
322	 *   抛错并保留全部材料,不猜测。
323	 * 旧备份与待换入新内容必须是常规文件,否则按被篡改处理,中止回滚。
324	 */
325	function rollbackPass(dir: string, journal: Journal): void {
326	  for (const f of journal.files) {
327	    const target = join(dir, f.name);
328	    const oldPath = target + OLD_SUFFIX;
329	    const newPath = target + NEW_SUFFIX;
330	    if (isRegularFile(oldPath)) {
331	      // hadOld=false 的文件按定义从不产生旧备份;若出现则与日志矛盾,不据此
332	      // 复活内容(否则会把事务造成的缺文件错误还原成某个来历不明的文件)。
333	      if (!f.hadOld) {
334	        throw new StoreError(`cannot roll back ${target}: backup exists but the journal records no original file`);
335	      }
336	      if (existsSync(target)) {
337	        if (!isRegularFile(target)) {
338	          throw new StoreError(`cannot roll back ${target}: target exists but is not a regular file`);
339	        }
340	        rmSync(target);
341	      }
342	      renameSync(oldPath, target);
343	    } else if (existsSync(oldPath)) {
344	      throw new StoreError(`restore backup ${oldPath} is not a regular file`);
345	    } else if (f.hadOld) {
346	      if (!existsSync(target)) {
347	        throw new StoreError(`cannot roll back ${target}: both the original and its backup are missing`);
348	      }
349	      if (!isRegularFile(target)) {
350	        throw new StoreError(`cannot roll back ${target}: restored original is not a regular file`);
351	      }
352	      // 原位已是常规文件:上一轮已还原完成,保持不动(绝不误删)。
353	    } else {
354	      // 原本缺失:清除事务换入的内容(原位或残留新临时文件),恢复为缺失。
355	      if (existsSync(newPath)) {
356	        if (!isRegularFile(newPath)) {
357	          throw new StoreError(`restore temp file ${newPath} is not a regular file`);
358	        }
359	        rmSync(newPath);
360	      }
361	      if (existsSync(target)) {
362	        if (!isRegularFile(target)) {
363	          throw new StoreError(`cannot restore missing state for ${target}: target is not a regular file`);
364	        }
365	        rmSync(target);
366	      }
367	    }
368	  }
369	}
370	
371	/** 回滚收尾:删除残留新临时文件,再删日志。旧文件备份已全部换回原位。 */
372	function rollbackCleanup(dir: string, journal: Journal): void {
373	  for (const f of journal.files) {
374	    const newPath = join(dir, f.name) + NEW_SUFFIX;
375	    if (existsSync(newPath)) {
376	      // 该名字属于本次事务的临时命名空间;正常产物必为常规文件。即便是异常
377	      // 占位(如目录),也随回滚一并递归清除,不影响业务存储。
378	      rmSync(newPath, { recursive: true, force: true });
379	    }
380	    const oldPath = join(dir, f.name) + OLD_SUFFIX;
381	    if (existsSync(oldPath)) {
382	      // 正常不应残留;若仍在则回滚未完成,保留材料并报错,不删日志。
383	      throw new StoreError(`restore backup ${oldPath} was not restored; rollback is incomplete`);
384	    }
385	  }
386	  rmSync(join(dir, JOURNAL_NAME));
387	}
388	
389	// ---------------------------------------------------------------------------
390	// 前滚(提交完整快照)——幂等,可跨中断续接
391	// ---------------------------------------------------------------------------
392	
393	/**
394	 * 前滚到完整快照状态,逐文件幂等,可在任意一步中断后续接。每个文件只有崩溃
395	 * 可达的三种状态:
396	 *   未动:原位=旧内容(hadOld 时)或原位缺失,新临时在,旧备份无;
397	 *   旧已移走:原位缺失,新临时在,旧备份在;
398	 *   已换入:原位=新内容,新临时无,旧备份在(hadOld 时);原本缺失的文件
399	 *           (hadOld=false)已换入时旧备份按定义不存在。
400	 * 判据:新临时还在就说明该文件尚未换入——原位若有旧内容先移为旧备份,再把
401	 * 新临时换入;新临时不在则原位必须已是常规文件。关键不变量:日志仍在时
402	 * 收尾尚未运行(收尾先删日志再删旧备份),故 hadOld 的已换入文件必仍带旧
403	 * 备份;原位是常规内容、新临时与旧备份却都不在属于无法可靠判定的状态,
404	 * 直接抛错并保留材料,绝不把旧内容误当新内容而提交混合状态。
405	 */
406	function rollForwardPass(dir: string, journal: Journal): void {
407	  for (const f of journal.files) {
408	    const target = join(dir, f.name);
409	    const newPath = target + NEW_SUFFIX;
410	    const oldPath = target + OLD_SUFFIX;
411	    if (existsSync(newPath)) {
412	      if (!isRegularFile(newPath)) {
413	        throw new StoreError(`restore temp file ${newPath} is not a regular file`);
414	      }
415	      if (existsSync(target)) {
416	        // 旧内容仍在原位,先移为备份。
417	        if (!isRegularFile(target)) {
418	          throw new StoreError(`cannot commit ${target}: target exists but is not a regular file`);
419	        }
420	        if (existsSync(oldPath)) {
421	          throw new StoreError(`cannot commit ${target}: both the original and its backup are present`);
422	        }
423	        if (!f.hadOld) {
424	          // 日志称原本缺失,原位却有内容:与日志矛盾,不猜测。
425	          throw new StoreError(`cannot commit ${target}: journal says it was originally absent`);
426	        }
427	        renameSync(target, oldPath);
428	      }
429	      renameSync(newPath, target);
430	    } else if (isRegularFile(target)) {
431	      // 新临时已不在:视为已换入。hadOld 的文件此刻必仍有旧备份(日志还在,
432	      // 收尾未运行);缺失则状态无法可靠判定,中止而不猜。
433	      if (f.hadOld && !existsSync(oldPath)) {
434	        throw new StoreError(
435	          `cannot determine state of ${target}: neither its restore temp nor its backup exists`,
436	        );
437	      }
438	    } else {
439	      throw new StoreError(`cannot commit ${target}: business store is missing or not a regular file`);
440	    }
441	  }
442	  for (const f of journal.files) {
443	    if (!isRegularFile(join(dir, f.name))) {
444	      throw new StoreError(`cannot commit ${join(dir, f.name)}: business store is missing or not a regular file`);
445	    }
446	  }
447	}
448	
449	/** 前滚收尾:删除日志与旧文件备份(新临时文件已全部换入)。 */
450	function rollForwardCleanup(dir: string, journal: Journal): void {
451	  for (const f of journal.files) {
452	    const newPath = join(dir, f.name) + NEW_SUFFIX;
453	    if (existsSync(newPath)) {
454	      throw new StoreError(`restore temp file ${newPath} still present; commit is incomplete`);
455	    }
456	  }
457	  rmSync(join(dir, JOURNAL_NAME));
458	  for (const f of journal.files) {
459	    const oldPath = join(dir, f.name) + OLD_SUFFIX;
460	    if (existsSync(oldPath)) rmSync(oldPath);
461	  }
462	}
463	
464	// ---------------------------------------------------------------------------
465	// 启动自恢复(持锁调用)
466	// ---------------------------------------------------------------------------
467	
468	/**
469	 * 续接未完成的恢复。依据日志阶段决定方向:
470	 * - preparing:优先前滚为完整快照;失败再回滚为完整旧库(两方向皆可)。
471	 * - committing:只能前滚;失败不回滚,保留材料并报错,绝不产生混合判定。
472	 * - rolling-back:只能继续还原完整旧库,不能改为前滚。
473	 * - done:完成前滚收尾。
474	 * 成功返回 null;无法可靠判定或完成时返回错误消息,材料一律保留。
475	 */
476	function resumeRestore(dir: string, journal: Journal): string | null {
477	  try {
478	    if (journal.phase === 'preparing') {
479	      rollForwardPass(dir, journal);
480	      writeJournalPhase(dir, journal, 'committing');
481	      rollForwardCleanup(dir, journal);
482	      err('completed an interrupted restore: snapshot state committed');
483	      return null;
484	    }
485	    if (journal.phase === 'committing' || journal.phase === 'done') {
486	      if (journal.phase === 'committing') {
487	        rollForwardPass(dir, journal);
488	        writeJournalPhase(dir, journal, 'done');
489	      }
490	      rollForwardCleanup(dir, journal);
491	      err('completed an interrupted restore: snapshot state committed');
492	      return null;
493	    }
494	    // rolling-back:进入回滚后只能继续还原完整旧库。
495	    rollbackPass(dir, journal);
496	    rollbackCleanup(dir, journal);
497	    err('continued an interrupted rollback: previous state restored');
498	    return null;
499	  } catch (e) {
500	    // preparing 阶段前滚失败时尚未进入失败回滚,可收敛为完整旧库。
501	    if (journal.phase === 'preparing') {
502	      try {
503	        writeJournalPhase(dir, journal, 'rolling-back');
504	        rollbackPass(dir, journal);
505	        rollbackCleanup(dir, journal);
506	        err('rolled back an interrupted restore: previous state restored');
507	        return null;
508	      } catch (re) {
509	        return (
510	          `cannot recover data directory ${dir} to a consistent state: ${(re as Error).message}; ` +
511	          `restore materials were kept in the directory; do not delete ${JOURNAL_NAME} or ` +
512	          `'*${OLD_SUFFIX}'/'*${NEW_SUFFIX}' files, then run any meterwatch command again`
513	        );
514	      }
515	    }
516	    return (
517	      `cannot complete interrupted restore for data directory ${dir}: ${(e as Error).message}; ` +
518	      `restore materials were kept (${JOURNAL_NAME}, '*${OLD_SUFFIX}', '*${NEW_SUFFIX}'); ` +
519	      `resolve the underlying read/write problem and run any meterwatch command again`
520	    );
521	  }
522	}
523	
524	/**
525	 * 任一命令启动时(持锁)调用:若上次恢复被中断,先把数据目录续接为完整
526	 * 快照状态或完整旧状态,绝不留下或查询混合状态。没有日志时清理可能残留
527	 * 的临时文件。成功(或无需恢复)返回 null,无法完成返回错误消息。
528	 */
529	function recoverIfNeeded(dir: string): string | null {
530	  const journalPath = join(dir, JOURNAL_NAME);
531	  if (existsSync(journalPath)) {
532	    let journal: Journal | null = null;
533	    try {
534	      journal = parseJournal(JSON.parse(readFileSync(journalPath, 'utf8')));
535	    } catch {
536	      journal = null;
537	    }
538	    if (journal === null) {
539	      return (
540	        `cannot recover data directory ${dir}: restore journal ${journalPath} is unreadable or invalid; ` +
541	        `the directory may hold restore materials in an unknown state - nothing was deleted; ` +
542	        `inspect ${JOURNAL_NAME} and '*${OLD_SUFFIX}'/'*${NEW_SUFFIX}' files before retrying`
543	      );
544	    }
545	    return resumeRestore(dir, journal);
546	  }
547	  // 无日志:提交未开始(残留新临时文件)或已完整完成(残留旧文件备份)。
548	  // 这些残留不属于任何活动事务,清理即可;清理失败明确报错,不继续启动。
549	  for (const path of storeFiles()) {
550	    for (const leftover of [path + NEW_SUFFIX, path + OLD_SUFFIX]) {
551	      if (existsSync(leftover)) {
552	        try {
553	          rmSync(leftover);
554	        } catch (e) {
555	          return `cannot clean up interrupted restore leftover ${leftover}: ${(e as Error).message}`;
556	        }
557	      }
558	    }
559	  }
560	  // 日志阶段翻转时用的临时名(原子换名前被杀会留下死临时),不影响判定。
561	  for (const entry of readdirSync(dir)) {
562	    if (entry.startsWith(`${JOURNAL_NAME}.tmp-`)) {
563	      try {
564	        rmSync(join(dir, entry));
565	      } catch (e) {
566	        return `cannot clean up interrupted restore leftover ${join(dir, entry)}: ${(e as Error).message}`;
567	      }
568	    }
569	  }
570	  return null;
571	}
572	
573	// ---------------------------------------------------------------------------
574	// 目录操作权 + 自恢复:所有命令的统一入口协调
575	// ---------------------------------------------------------------------------
576	
577	/**
578	 * 取得数据目录的排他操作权并先处理未完成恢复,然后运行业务动作。
579	 *
580	 * 任何命令(含无参数、--help/-h 与非法参数入口)都必须先完成本协调:
581	 * - 目录不存在则创建(数据目录本身可由本工具建立);
582	 * - 锁被存活进程占用:返回 1,不读写业务存储、不清理对方事务材料;
583	 * - 自恢复无法可靠完成:返回 1,不运行业务动作;
584	 * - 成功后运行业务动作并沿用其退出码,释放锁。
585	 */
586	export function withDirectoryCoordination<T>(action: () => T): T | number {
587	  const dir = dataDirPath();
588	  try {
589	    mkdirSync(dir, { recursive: true });
590	  } catch (e) {
591	    err(`cannot access data directory ${dir}: ${(e as Error).message}`);
592	    return 1;
593	  }
594	  const lockError = acquireLock(dir);
595	  if (lockError !== null) {
596	    err(lockError);
597	    return 1;
598	  }
599	  try {
600	    const recoveryError = recoverIfNeeded(dir);
601	    if (recoveryError !== null) {
602	      err(recoveryError);
603	      return 1;
604	    }
605	    return action();
606	  } finally {
607	    releaseLock(dir);
608	  }
609	}
610	
611	/**
612	 * 把三个业务存储的新内容作为一次恢复提交。调用方已持有目录锁。
613	 *
614	 * 阶段:
615	 *  1. preparing:写全部新内容到临时文件,再原子写日志。失败或中断都不影响
616	 *     现有业务文件(此阶段中断下次可前滚或回滚)。
617	 *  2. committing:整体换名(旧文件移为备份,新文件换入)。中断只能前滚。
618	 *  3. 受控失败:先置 rolling-back(此后只能还原旧库),再幂等回滚。
619	 *  4. 成功:置 done 并清理日志与旧备份。
620	 */
621	function commitRestore(dir: string, files: Array<{ path: string; body: string }>): void {
622	  const journalPath = join(dir, JOURNAL_NAME);
623	  const journal: Journal = {
624	    phase: 'preparing',
625	    files: files.map((f) => ({ name: basename(f.path), hadOld: existsSync(f.path) })),
626	  };
627	
628	  // 阶段一:准备。此阶段失败不改变业务文件;不留日志(下次按残留清理)。
629	  try {
630	    for (const f of files) {
631	      writeFileSync(f.path + NEW_SUFFIX, f.body, 'utf8');
632	    }
633	    writeJournalPhase(dir, journal, 'preparing');
634	  } catch (e) {
635	    for (const f of files) {
636	      try {
637	        if (existsSync(f.path + NEW_SUFFIX)) rmSync(f.path + NEW_SUFFIX);
638	      } catch {
639	        // 清理失败不掩盖原始错误;无日志,残留由下次启动清理。
640	      }
641	    }
642	    throw new StoreError(`cannot prepare restore in ${dir}: ${(e as Error).message}; nothing was changed`);
643	  }
644	
645	  // 阶段二:整体换名提交。
646	  try {
647	    writeJournalPhase(dir, journal, 'committing');
648	    for (const f of journal.files) {
649	      const target = join(dir, f.name);
650	      if (existsSync(target)) {
651	        renameSync(target, target + OLD_SUFFIX);
652	      }
653	    }
654	    for (const f of journal.files) {
655	      const target = join(dir, f.name);
656	      renameSync(target + NEW_SUFFIX, target);
657	    }
658	  } catch (e) {
659	    // 受控失败:进入 rolling-back 后只能继续还原完整旧库(幂等,可中断)。
660	    try {
661	      writeJournalPhase(dir, journal, 'rolling-back');
662	    } catch (we) {
663	      throw new StoreError(
664	        `restore failed (${(e as Error).message}) and the rollback could not be started ` +
665	          `(${ (we as Error).message}); data directory ${dir} keeps its restore materials - ` +
666	          `run any meterwatch command again to continue the rollback`,
667	      );
668	    }
669	    try {
670	      rollbackPass(dir, journal);
671	      rollbackCleanup(dir, journal);
672	    } catch (re) {
673	      throw new StoreError(
674	        `restore failed (${(e as Error).message}); rollback is in progress and could not finish ` +
675	          `(${ (re as Error).message}); data directory ${dir} keeps all materials needed to continue - ` +
676	          `run any meterwatch command again to finish restoring the previous state`,
677	      );
678	    }
679	    throw new StoreError(`restore failed: ${(e as Error).message}; previous state restored`);
680	  }
681	
682	  // 阶段三:提交已落地,记录完成并清理备份。清理失败不影响快照一致性,
683	  // 但仍作为错误上报;下次启动会完成收尾。
684	  try {
685	    writeJournalPhase(dir, journal, 'done');
686	    rollForwardCleanup(dir, journal);
687	  } catch (e) {
688	    throw new StoreError(
689	      `snapshot state was committed but post-commit cleanup failed: ${(e as Error).message}; ` +
690	        `run any meterwatch command again to finish cleanup`,
691	    );
692	  }
693	}
694	
695	/** 各存储内容汇总的一行数量报告。 */
696	function countsReport(data: StoreData, alerts: AlertState, groups: Group[]): string {
697	  const versions = groups.reduce((n, g) => n + g.versions.length, 0);
698	  return (
699	    `${data.readings.length} reading(s), ${data.corrections.length} correction(s), ` +
700	    `${data.undos.length} undo(s), ${groups.length} group(s) (${versions} member version(s)), ` +
701	    `${alerts.rules.length} rule(s), ${alerts.alerts.length} alert(s)`
702	  );
703	}
704	
705	/**
706	 * 导出全库快照。在目录操作权与自恢复协调之内运行(见
707	 * withDirectoryCoordination):只读取业务存储,不改写业务数据;输出文件必须
708	 * 位于数据目录之外且不得已存在。返回进程退出码。
709	 */
710	export function cmdBackup(outPath: string): number {
711	  const dir = dataDirPath();
712	  if (isInsideDir(dir, outPath)) {
713	    err(`snapshot file '${outPath}' must be located outside the data directory ${dir}`);
714	    return 2;
715	  }
716	
717	  let data: StoreData;
718	  let alerts: AlertState;
719	  let groups: Group[];
720	  try {
721	    data = loadData(dataFilePath());
722	    alerts = loadAlertState(alertFilePath());
723	    groups = loadGroups(groupFilePath());
724	  } catch (e) {
725	    if (e instanceof StoreError) {
726	      err(e.message);
727	      return 1;
728	    }
729	    throw e;
730	  }
731	
732	  const problems = validateStores(data, alerts, groups);
733	  if (problems.length > 0) {
734	    for (const p of problems) err(p);
735	    err(`backup rejected: ${problems.length} consistency problem(s); no snapshot was written`);
736	    return 1;
737	  }
738	
739	  const payload = {
740	    readings: serializeStoreData(data),
741	    alerts: serializeAlertState(alerts),
742	    groups: serializeGroups(groups),
743	  };
744	  const checksum = createHash('sha256').update(JSON.stringify(payload), 'utf8').digest('hex');
745	  const body =
746	    JSON.stringify(
747	      {
748	        format: SNAPSHOT_FORMAT,
749	        version: SNAPSHOT_VERSION,
750	        checksum: `sha256:${checksum}`,
751	        payload,
752	      },
753	      null,
754	      2,
755	    ) + '\n';
756	
757	  // 先写临时文件,再原子链接为最终名:已存在的输出拒绝覆盖,失败不留下
758	  // 可被当作成功快照的输出。
759	  const out = resolve(outPath);
760	  const tmp = `${out}.tmp-${process.pid}`;
761	  try {
762	    writeFileSync(tmp, body, 'utf8');
763	    linkSync(tmp, out);
764	  } catch (e) {
765	    if ((e as NodeJS.ErrnoException).code === 'EEXIST') {
766	      err(`output file '${outPath}' already exists; refusing to overwrite`);
767	    } else {
768	      err(`cannot write snapshot '${outPath}': ${(e as Error).message}`);
769	    }
770	    return 1;
771	  } finally {
772	    try {
773	      rmSync(tmp);
774	    } catch {
775	      // 临时文件可能未创建;清理失败不影响结果。
776	    }
777	  }
778	
779	  console.log(`snapshot written to '${outPath}': ${countsReport(data, alerts, groups)}`);
780	  return 0;
781	}
782	
783	/**
784	 * 从快照整库恢复。在目录操作权与自恢复协调之内运行:协调完成后才读取并
785	 * 校验快照(故损坏的当前库不影响恢复,恢复不以解析旧库为前提)。快照须通过
786	 * 格式版本与完整性校验,且三个业务存储的结构与关联一致,否则不开始替换。
787	 * 成功后业务状态完全等于快照。返回进程退出码。
788	 */
789	export function cmdRestore(snapshotPath: string): number {
790	  const dir = dataDirPath();
791	  if (isInsideDir(dir, snapshotPath)) {
792	    err(`snapshot file '${snapshotPath}' must be located outside the data directory ${dir}`);
793	    return 2;
794	  }
795	
796	  let text: string;
797	  try {
798	    text = readFileSync(resolve(snapshotPath), 'utf8');
799	  } catch (e) {
800	    err(`cannot read snapshot '${snapshotPath}': ${(e as Error).message}`);
801	    return 1;
802	  }
803	  let envelope: unknown;
804	  try {
805	    envelope = JSON.parse(text);
806	  } catch {
807	    err(`snapshot '${snapshotPath}' is corrupted (invalid JSON or truncated); nothing was restored`);
808	    return 1;
809	  }
810	  const env = envelope as Record<string, unknown>;
811	  if (env === null || typeof env !== 'object' || env.format !== SNAPSHOT_FORMAT) {
812	    err(`snapshot '${snapshotPath}' is not a meterwatch snapshot; nothing was restored`);
813	    return 1;
814	  }
815	  if (env.version !== SNAPSHOT_VERSION) {
816	    err(
817	      `snapshot '${snapshotPath}' has unsupported format version ${String(env.version)} ` +
818	        `(this build supports version ${SNAPSHOT_VERSION}); nothing was restored`,
819	    );
820	    return 1;
821	  }
822	  const payloadText = JSON.stringify(env.payload) ?? '';
823	  const checksum = createHash('sha256').update(payloadText, 'utf8').digest('hex');
824	  if (typeof env.checksum !== 'string' || env.checksum !== `sha256:${checksum}`) {
825	    err(`snapshot '${snapshotPath}' failed its integrity check; nothing was restored`);
826	    return 1;
827	  }
828	
829	  const payload = env.payload as Record<string, unknown>;
830	  let data: StoreData;
831	  let alerts: AlertState;
832	  let groups: Group[];
833	  try {
834	    data = parseStoreData(payload?.readings, `snapshot '${snapshotPath}' readings store`);
835	    alerts = parseAlertState(payload?.alerts, `snapshot '${snapshotPath}' alerts store`);
836	    groups = parseGroups(payload?.groups, `snapshot '${snapshotPath}' groups store`);
837	  } catch (e) {
838	    if (e instanceof StoreError) {
839	      err(`${e.message}; nothing was restored`);
840	      return 1;
841	    }
842	    throw e;
843	  }
844	  const problems = validateStores(data, alerts, groups);
845	  if (problems.length > 0) {
846	    for (const p of problems) err(p);
847	    err(`restore rejected: snapshot has ${problems.length} consistency problem(s); nothing was restored`);
848	    return 1;
849	  }
850	
851	  // 快照校验全部通过后才开始替换;调用方已持有目录操作权。
852	  try {
853	    commitRestore(dir, [
854	      { path: dataFilePath(), body: JSON.stringify(serializeStoreData(data), null, 2) + '\n' },
855	      { path: alertFilePath(), body: JSON.stringify(serializeAlertState(alerts), null, 2) + '\n' },
856	      { path: groupFilePath(), body: JSON.stringify(serializeGroups(groups), null, 2) + '\n' },
857	    ]);
858	  } catch (e) {
859	    if (e instanceof StoreError) {
860	      err(e.message);
861	      return 1;
862	    }
863	    throw e;
864	  }
865	
866	  console.log(`restored from snapshot '${snapshotPath}': ${countsReport(data, alerts, groups)}`);
867	  return 0;
868	}
