307	interface ParsedOptions {
308	  devices: string[];
309	  from?: number;
310	  to?: number;
311	  tz?: string;
312	  maxInterval?: number;
313	}
314	
315	/** 解析最大采样间隔限制(正整数秒数);无效返回 null。 */
316	function parseMaxInterval(raw: string): number | null {
317	  const v = raw.trim();
318	  if (!/^\d+$/.test(v)) return null;
319	  const n = Number(v);
320	  if (!Number.isSafeInteger(n) || n < 1) return null;
321	  return n;
322	}
323	
324	/** 解析 --device/--from/--to(及允许时的 --tz、--max-interval)选项;出错返回错误消息字符串。 */
325	function parseOptions(rest: string[], allowTz = false, allowMaxInterval = false): ParsedOptions | string {
326	  const devices: string[] = [];
327	  let from: number | undefined;
328	  let to: number | undefined;
329	  let tz: string | undefined;
330	  let maxInterval: number | undefined;
331	  for (let i = 0; i < rest.length; i++) {
332	    let opt = rest[i];
333	    let value: string | undefined;
334	    const eq = opt.indexOf('=');
335	    if (opt.startsWith('--') && eq !== -1) {
336	      value = opt.slice(eq + 1);
337	      opt = opt.slice(0, eq);
338	    } else if (opt.startsWith('--')) {
339	      value = rest[i + 1];
340	      if (value === undefined) return `选项 '${opt}' 缺少值`;
341	      i++;
342	    } else {
343	      return `无法识别的参数 '${opt}'`;
344	    }
345	    if (opt === '--device') {
346	      if (value.trim() === '') return "'--device' 的值不能为空";
347	      devices.push(value);
348	    } else if (opt === '--from' || opt === '--to') {
349	      const ts = parseIso8601(value.trim());
350	      if (ts === null) {
351	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
