379	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
380	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
381	  const out = new Map<string, string[]>();
382	  for (let i = 0; i < rest.length; i++) {
383	    let opt = rest[i];
384	    let value: string | undefined;
385	    const eq = opt.indexOf('=');
386	    if (opt.startsWith('--') && eq !== -1) {
387	      value = opt.slice(eq + 1);
388	      opt = opt.slice(0, eq);
389	    } else if (opt.startsWith('--')) {
390	      value = rest[i + 1];
391	      if (value === undefined) return `选项 '${opt}' 缺少值`;
392	      i++;
393	    } else {
394	      return `无法识别的参数 '${opt}'`;
395	    }
396	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
397	    const list = out.get(opt);
398	    if (list) list.push(value);
399	    else out.set(opt, [value]);
400	  }
401	  return out;
402	}
