712	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
713	  const segments: string[][] = [[]];
714	  for (const tok of rest) {
715	    if (tok === '--item') segments.push([]);
716	    else segments[segments.length - 1].push(tok);
717	  }
718	  const headFlags = parseFlags(segments[0], ['--request']);
719	  if (typeof headFlags === 'string') return headFlags;
720	  const requestRaw = oneFlag(headFlags, '--request');
721	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
722	  const requestId = requestRaw.trim();
723	  if (requestId === '') return '请求标识不能为空';
724	  const itemSegs = segments.slice(1);
725	  if (itemSegs.length === 0) {
726	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
727	  }
728	  const items: CorrectionItem[] = [];
729	  for (const seg of itemSegs) {
730	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
731	    if (typeof flags === 'string') return flags;
732	    const deviceRaw = oneFlag(flags, '--device');
733	    const atRaw = oneFlag(flags, '--at');
734	    const expectRaw = oneFlag(flags, '--expect');
735	    const setRaw = oneFlag(flags, '--set');
736	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
737	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
738	    }
739	    const device = deviceRaw.trim();
740	    if (device === '') return "'--device' 的值不能为空";
741	    const ts = parseIso8601(atRaw.trim());
742	    if (ts === null) {
743	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
744	    }
745	    const expectedMilli = parseKwh(expectRaw.trim());
746	    if (expectedMilli === null) {
747	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
748	    }
749	    const replacementMilli = parseKwh(setRaw.trim());
750	    if (replacementMilli === null) {
751	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
752	    }
753	    items.push({ device, ts, expectedMilli, replacementMilli });
754	  }
755	  return { requestId, items };
756	}
