800	  }
801	
802	  if (cmd === 'readings') {
803	    const parsed = parseOptions(rest);
804	    if (typeof parsed === 'string') return usageError(parsed);
805	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
806	      return usageError('查询起点必须早于终点(--from < --to)');
807	    }
