823	    }
824	    return cmdDaily({
825	      devices: parsed.devices,
826	      from: parsed.from,
827	      to: parsed.to,
828	      tz: parsed.tz,
829	      maxInterval: parsed.maxInterval,
830	    });
831	  }
832	
833	  if (cmd === 'rule') return cmdRule(rest);
834	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
835	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
836	  if (cmd === 'group') return cmdGroup(rest);
837	  if (cmd === 'correct') return cmdCorrectEntry(rest);
838	  if (cmd === 'undo') return cmdUndoEntry(rest);
839	
840	  if (cmd === 'corrections') {
841	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
842	    return cmdCorrections();
843	  }
844	
845	  if (cmd === 'ack') {
846	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
847	    const alertId = rest[0].trim();
848	    if (alertId === '') return usageError('告警标识不能为空');
849	    return cmdAck(alertId);
850	  }
