  const checksum = createHash('sha256').update(payloadText, 'utf8').digest('hex');
  if (typeof env.checksum !== 'string' || env.checksum !== `sha256:${checksum}`) {
    err(`snapshot '${snapshotPath}' failed its integrity check; nothing was restored`);
    return 1;
  }

